@Test
void 직접_판단시킨다() {
    AuthorizationManager<Object> manager =
            AuthorityAuthorizationManager.hasRole("ADMIN");

    Authentication user = UsernamePasswordAuthenticationToken.authenticated(
            "u", null, List.of(new SimpleGrantedAuthority("ROLE_USER")));
    Authentication admin = UsernamePasswordAuthenticationToken.authenticated(
            "a", null, List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));

    System.out.println(">>> user  = " + manager.check(() -> user, null));
    System.out.println(">>> admin = " + manager.check(() -> admin, null));
}

