# --- Supplier 가 안 불리는 것을 본다 ---

@Test
void permitAll_은_인증을_안_본다() {
    AtomicInteger calls = new AtomicInteger();
    Supplier<Authentication> supplier = () -> {
        calls.incrementAndGet();
        return null;
    };

    new AuthenticatedAuthorizationManager<>().check(supplier, null);
    System.out.println(">>> authenticated 가 부른 횟수 = " + calls.get());

    calls.set(0);
    AuthorizationManager<Object> permitAll = (a, o) ->
            new AuthorizationDecision(true);
    permitAll.check(supplier, null);
    System.out.println(">>> permitAll 이 부른 횟수    = " + calls.get());
}

$ ./gradlew test --tests ManagerTest

