public class IpAuthorizationManager
        implements AuthorizationManager<RequestAuthorizationContext> {
    private final IpAddressMatcher matcher;

    @Override
    public AuthorizationDecision check(Supplier<Authentication> auth,
            RequestAuthorizationContext context) {
        boolean ok = matcher.matches(context.getRequest());
        System.out.println(">>> ip " + context.getRequest().getRemoteAddr()
                + " -> " + ok);
        return new AuthorizationDecision(ok);
    }
}

http.authorizeHttpRequests(a -> a
